SUBROUTINE SETUP_TRANS0(KOUT, KERR, KPRINTLEV, KMAX_RESOL, KPROMATR, KPRGPNS, KPRGPEW, KPRTRW, &
  &                     KCOMBFLEN, LDMPOFF, LDSYNC_TRANS, KTRANS_SYNC_LEVEL, LDEQ_REGIONS, &
  &                     K_REGIONS_NS, K_REGIONS_EW, K_REGIONS, PRAD, LDALLOPERM, KOPT_MEMORY_TR)

USE PARKIND1, ONLY: JPIM, JPRD
USE, INTRINSIC :: ISO_C_BINDING, ONLY: C_INT, C_BOOL, C_DOUBLE, C_PTR, C_LOC, C_NULL_PTR

IMPLICIT NONE

INTERFACE
SUBROUTINE SETUP_TRANS0_CPP_BINDING(KOUT, KERR, KPRINTLEV, KMAX_RESOL, KPROMATR, KPRGPNS, KPRGPEW, &
  &                                 KPRTRW, LDMPOFF, LDSYNC_TRANS, KTRANS_SYNC_LEVEL, &
  &                                 LDEQ_REGIONS, PRAD, LDALLOPERM, KOPT_MEMORY_TR, K_REGIONS_NS, &
  &                                 K_REGIONS_EW, K_REGIONS) BIND(C, NAME="setup_trans0")
  USE, INTRINSIC :: ISO_C_BINDING, ONLY: C_INT, C_PTR
  TYPE(C_PTR),         VALUE,    INTENT(IN)    :: KOUT
  TYPE(C_PTR),         VALUE,    INTENT(IN)    :: KERR
  TYPE(C_PTR),         VALUE,    INTENT(IN)    :: KPRINTLEV
  TYPE(C_PTR),         VALUE,    INTENT(IN)    :: KMAX_RESOL
  TYPE(C_PTR),         VALUE,    INTENT(IN)    :: KPROMATR
  TYPE(C_PTR),         VALUE,    INTENT(IN)    :: KPRGPNS
  TYPE(C_PTR),         VALUE,    INTENT(IN)    :: KPRGPEW
  TYPE(C_PTR),         VALUE,    INTENT(IN)    :: KPRTRW
  TYPE(C_PTR),         VALUE,    INTENT(IN)    :: LDMPOFF
  TYPE(C_PTR),         VALUE,    INTENT(IN)    :: LDSYNC_TRANS
  TYPE(C_PTR),         VALUE,    INTENT(IN)    :: KTRANS_SYNC_LEVEL
  TYPE(C_PTR),         VALUE,    INTENT(IN)    :: LDEQ_REGIONS
  TYPE(C_PTR),         VALUE,    INTENT(IN)    :: PRAD
  TYPE(C_PTR),         VALUE,    INTENT(IN)    :: LDALLOPERM
  TYPE(C_PTR),         VALUE,    INTENT(IN)    :: KOPT_MEMORY_TR
  TYPE(C_PTR),         VALUE,    INTENT(IN)    :: K_REGIONS_NS
  TYPE(C_PTR),         VALUE,    INTENT(IN)    :: K_REGIONS_EW
  INTEGER(KIND=C_INT), OPTIONAL, INTENT(INOUT) :: K_REGIONS(*)
END SUBROUTINE SETUP_TRANS0_CPP_BINDING
END INTERFACE

INTEGER(KIND=JPIM), OPTIONAL, INTENT(IN)  :: KOUT
INTEGER(KIND=JPIM), OPTIONAL, INTENT(IN)  :: KERR
INTEGER(KIND=JPIM), OPTIONAL, INTENT(IN)  :: KPRINTLEV
INTEGER(KIND=JPIM), OPTIONAL, INTENT(IN)  :: KMAX_RESOL
INTEGER(KIND=JPIM), OPTIONAL, INTENT(IN)  :: KPROMATR
INTEGER(KIND=JPIM), OPTIONAL, INTENT(IN)  :: KPRGPNS
INTEGER(KIND=JPIM), OPTIONAL, INTENT(IN)  :: KPRGPEW
INTEGER(KIND=JPIM), OPTIONAL, INTENT(IN)  :: KPRTRW
INTEGER(KIND=JPIM), OPTIONAL, INTENT(IN)  :: KCOMBFLEN
LOGICAL,            OPTIONAL, INTENT(IN)  :: LDMPOFF
LOGICAL,            OPTIONAL, INTENT(IN)  :: LDSYNC_TRANS
INTEGER(KIND=JPIM), OPTIONAL, INTENT(IN)  :: KTRANS_SYNC_LEVEL
LOGICAL,            OPTIONAL, INTENT(IN)  :: LDEQ_REGIONS
INTEGER(KIND=JPIM), OPTIONAL, INTENT(OUT) :: K_REGIONS_NS
INTEGER(KIND=JPIM), OPTIONAL, INTENT(OUT) :: K_REGIONS_EW
INTEGER(KIND=JPIM), OPTIONAL, INTENT(OUT) :: K_REGIONS(:)
REAL(KIND=JPRD),    OPTIONAL, INTENT(IN)  :: PRAD
LOGICAL,            OPTIONAL, INTENT(IN)  :: LDALLOPERM
INTEGER(KIND=JPIM), OPTIONAL, INTENT(IN)  :: KOPT_MEMORY_TR

! C-interoperable handles for the optional arguments. A null C pointer indicates the argument was
! not present in the Fortran call; otherwise the pointer targets a local temporary.
TYPE(C_PTR) :: KOUT_PTR, KERR_PTR, KPRINTLEV_PTR, KMAX_RESOL_PTR, KPROMATR_PTR
TYPE(C_PTR) :: KPRGPNS_PTR, KPRGPEW_PTR, KPRTRW_PTR, LMPOFF_PTR, LSYNC_TRANS_PTR
TYPE(C_PTR) :: KTRANS_SYNC_LEVEL_PTR, LEQ_REGIONS_PTR, PRAD_PTR, LALLOPERM_PTR
TYPE(C_PTR) :: KOPT_MEMORY_TR_PTR, K_REGIONS_NS_PTR, K_REGIONS_EW_PTR
INTEGER(KIND=C_INT),  TARGET :: IOUT, IERR, IPRINTLEV, IMAX_RESOL, IPROMATR, IPRGPNS, IPRGPEW
INTEGER(KIND=C_INT),  TARGET :: IPRTRW, ITRANS_SYNC_LEVEL, IOPT_MEMORY_TR, I_REGIONS_NS, I_REGIONS_EW
LOGICAL(KIND=C_BOOL), TARGET :: LMPOFF_C, LSYNC_TRANS_C, LEQ_REGIONS_C, LALLOPERM_C
REAL(KIND=C_DOUBLE),  TARGET :: ZRAD

INTEGER(KIND=JPIM) :: IOUT_HERE

! OPTIONAL, INTENT(IN) arguments
IF (PRESENT(KOUT)) THEN
  IOUT = KOUT
  KOUT_PTR = C_LOC(IOUT)
ELSE
  KOUT_PTR = C_NULL_PTR
ENDIF
IF (PRESENT(KERR)) THEN
  IERR = KERR
  KERR_PTR = C_LOC(IERR)
ELSE
  KERR_PTR = C_NULL_PTR
ENDIF
IF (PRESENT(KPRINTLEV)) THEN
  IPRINTLEV = KPRINTLEV
  KPRINTLEV_PTR = C_LOC(IPRINTLEV)
ELSE
  KPRINTLEV_PTR = C_NULL_PTR
ENDIF
IF (PRESENT(KMAX_RESOL)) THEN
  IMAX_RESOL = KMAX_RESOL
  KMAX_RESOL_PTR = C_LOC(IMAX_RESOL)
ELSE
  KMAX_RESOL_PTR = C_NULL_PTR
ENDIF
IF (PRESENT(KPROMATR)) THEN
  IPROMATR = KPROMATR
  KPROMATR_PTR = C_LOC(IPROMATR)
ELSE
  KPROMATR_PTR = C_NULL_PTR
ENDIF
IF (PRESENT(KPRGPNS)) THEN
  IPRGPNS = KPRGPNS
  KPRGPNS_PTR = C_LOC(IPRGPNS)
ELSE
  KPRGPNS_PTR = C_NULL_PTR
ENDIF
IF (PRESENT(KPRGPEW)) THEN
  IPRGPEW = KPRGPEW
  KPRGPEW_PTR = C_LOC(IPRGPEW)
ELSE
  KPRGPEW_PTR = C_NULL_PTR
ENDIF
IF (PRESENT(KPRTRW)) THEN
  IPRTRW = KPRTRW
  KPRTRW_PTR = C_LOC(IPRTRW)
ELSE
  KPRTRW_PTR = C_NULL_PTR
ENDIF
! This is deprecated so we won't bother to include it in the C++ layer
IF (PRESENT(KCOMBFLEN)) THEN
  IF (PRESENT(KOUT)) THEN
    IOUT_HERE = KOUT
  ELSE
    IOUT_HERE = 6
  ENDIF
  WRITE(IOUT_HERE,'(A)')
  WRITE(IOUT_HERE,'(A)') '*** WARNING ***'
  WRITE(IOUT_HERE,'(A)') 'KCOMBFLEN argument passed to SETUP_TRANS0 is deprecated'
  WRITE(IOUT_HERE,'(A)')
ENDIF
IF (PRESENT(LDMPOFF)) THEN
  LMPOFF_C = LDMPOFF
  LMPOFF_PTR = C_LOC(LMPOFF_C)
ELSE
  LMPOFF_PTR = C_NULL_PTR
ENDIF
IF (PRESENT(LDSYNC_TRANS)) THEN
  LSYNC_TRANS_C = LDSYNC_TRANS
  LSYNC_TRANS_PTR = C_LOC(LSYNC_TRANS_C)
ELSE
  LSYNC_TRANS_PTR = C_NULL_PTR
ENDIF
IF (PRESENT(KTRANS_SYNC_LEVEL)) THEN
  ITRANS_SYNC_LEVEL = KTRANS_SYNC_LEVEL
  KTRANS_SYNC_LEVEL_PTR = C_LOC(ITRANS_SYNC_LEVEL)
ELSE
  KTRANS_SYNC_LEVEL_PTR = C_NULL_PTR
ENDIF
IF (PRESENT(LDEQ_REGIONS)) THEN
  LEQ_REGIONS_C = LDEQ_REGIONS
  LEQ_REGIONS_PTR = C_LOC(LEQ_REGIONS_C)
ELSE
  LEQ_REGIONS_PTR = C_NULL_PTR
ENDIF
IF (PRESENT(PRAD)) THEN
  ZRAD = PRAD
  PRAD_PTR = C_LOC(ZRAD)
ELSE
  PRAD_PTR = C_NULL_PTR
ENDIF
IF (PRESENT(LDALLOPERM)) THEN
  LALLOPERM_C = LDALLOPERM
  LALLOPERM_PTR = C_LOC(LALLOPERM_C)
ELSE
  LALLOPERM_PTR = C_NULL_PTR
ENDIF
IF (PRESENT(KOPT_MEMORY_TR)) THEN
  IOPT_MEMORY_TR = KOPT_MEMORY_TR
  KOPT_MEMORY_TR_PTR = C_LOC(IOPT_MEMORY_TR)
ELSE
  KOPT_MEMORY_TR_PTR = C_NULL_PTR
ENDIF

! OPTIONAL, INTENT(OUT) arguments. The C++ layer writes into the local temporaries which are then
! copied back into the Fortran arguments after the call.
IF (PRESENT(K_REGIONS_NS)) THEN
  K_REGIONS_NS_PTR = C_LOC(I_REGIONS_NS)
ELSE
  K_REGIONS_NS_PTR = C_NULL_PTR
ENDIF
IF (PRESENT(K_REGIONS_EW)) THEN
  K_REGIONS_EW_PTR = C_LOC(I_REGIONS_EW)
ELSE
  K_REGIONS_EW_PTR = C_NULL_PTR
ENDIF

CALL SETUP_TRANS0_CPP_BINDING(KOUT_PTR, KERR_PTR, KPRINTLEV_PTR, KMAX_RESOL_PTR, KPROMATR_PTR, &
  &                           KPRGPNS_PTR, KPRGPEW_PTR, KPRTRW_PTR, LMPOFF_PTR, LSYNC_TRANS_PTR, &
  &                           KTRANS_SYNC_LEVEL_PTR, LEQ_REGIONS_PTR, PRAD_PTR, LALLOPERM_PTR, &
  &                           KOPT_MEMORY_TR_PTR, K_REGIONS_NS_PTR, K_REGIONS_EW_PTR, &
  &                           K_REGIONS=K_REGIONS)

! OPTIONAL, INTENT(OUT) arguments
IF (PRESENT(K_REGIONS_NS)) K_REGIONS_NS = I_REGIONS_NS
IF (PRESENT(K_REGIONS_EW)) K_REGIONS_EW = I_REGIONS_EW

END SUBROUTINE SETUP_TRANS0
